async function view_api() {
	if (this.api_info) return this.api_info;
	const { token } = this.options;
	const { config } = this;
	const headers = {};
	if (token) headers.Authorization = `Bearer ${token}`;
	if (!config) return;
	try {
		let response;
		let api_info;
		if (typeof window !== "undefined" && window.gradio_api_info) api_info = window.gradio_api_info;
		else {
			const url = join_urls(config.root, this.api_prefix, API_INFO_URL);
			response = await this.fetch(url, {
				headers,
				credentials: this.options.credentials ?? "same-origin"
			});
			if (!response.ok) throw new Error(BROKEN_CONNECTION_MSG);
			api_info = await response.json();
		}
		if ("api" in api_info) api_info = api_info.api;
		if (api_info.named_endpoints["/predict"] && !api_info.unnamed_endpoints["0"]) api_info.unnamed_endpoints[0] = api_info.named_endpoints["/predict"];
		return transform_api_info(api_info, config, this.api_map);
	} catch (e) {
		throw new Error("Could not get API info. " + e.message);
	}
}
